// One item per (niche × platform). Webhook → single combo; schedule → full matrix.
const src = $input.first().json;
const body = src.body;
const fromWebhook = !!body && typeof body === 'object' && Object.keys(body).length > 0;
const PLATFORMS = ['tiktok', 'instagram', 'youtube'];
const NICHES = ($env.DISCOVERY_NICHES || 'beauty,skincare,fmcg,food,fashion,parenting,tech,fitness').split(',').map(s => s.trim()).filter(Boolean);
const limit = Number($env.DISCOVERY_LIMIT_PER_COMBO || 50);
const out = [];
if (fromWebhook) {
  const platforms = body.platform ? [body.platform] : PLATFORMS;
  const niches = body.niche ? [body.niche] : NICHES.slice(0, 3);
  for (const platform of platforms) for (const niche of niches) out.push({ query: body.query || (niche + ' indonesia'), platform, niche, limit, source: 'webhook' });
} else {
  for (const platform of PLATFORMS) for (const niche of NICHES) out.push({ query: niche + ' indonesia', platform, niche, limit, source: 'schedule' });
}
return out.map(json => ({ json }));

// Maps raw scraper rows → Creator (docs/API.md). Emits batches of 25 for POST /webhooks/n8n creator.discovered.
const combo = $('Build scan matrix').all()[$('Loop combos').context.currentRunIndex].json;
const rows = $input.all().map(i => i.json).filter(r => r && typeof r === 'object' && !r.error);
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.]/g, '')); return Number.isFinite(n) ? n : 0; };
const first = (...vals) => vals.find(v => v !== undefined && v !== null && v !== '');
const stats = r => r.stats || r.statistics || {};
const creators = [];
const seen = new Set();
for (const r of rows) {
  const rawHandle = first(r.username, r.handle, r.uniqueId, r.screen_name, r.id, '');
  const handle = '@' + String(rawHandle).replace(/^@/, '').trim();
  if (handle.length < 2 || seen.has(handle)) continue;
  seen.add(handle);
  const followers = num(first(r.followersCount, r.followers, r.follower_count, r.subscriberCount, stats(r).followerCount));
  if (followers < 1000) continue; // below nano tier — skip
  const avgLikes = num(first(r.avgLikes, r.averageLikes, stats(r).heartCount && stats(r).videoCount ? stats(r).heartCount / stats(r).videoCount : null));
  const avgComments = num(first(r.avgComments, r.averageComments));
  const avgViews = num(first(r.avgViews, r.averageViews, stats(r).playCount));
  const er = r.engagementRate !== undefined ? num(r.engagementRate) : (followers ? +(((avgLikes + avgComments) / followers) * 100).toFixed(2) : 0);
  const email = String(first(r.businessEmail, r.public_email, r.email, '') || '').toLowerCase();
  const wa = String(first(r.whatsapp, r.businessPhone, r.public_phone_number, '') || '').replace(/[^0-9]/g, '');
  creators.push({
    handle,
    name: String(first(r.fullName, r.full_name, r.nickname, r.name, handle)).slice(0, 80),
    platform: combo.platform,
    followers,
    following: num(first(r.followsCount, r.following, r.followingCount, stats(r).followingCount)),
    posts: num(first(r.postsCount, r.posts, r.videoCount, stats(r).videoCount)),
    engagementRate: er, avgViews, avgLikes, avgComments,
    niche: [combo.niche],
    city: String(first(r.city, r.location, '') || '').slice(0, 40),
    languages: ['id'],
    bio: String(first(r.biography, r.bio, r.signature, '') || '').slice(0, 300),
    avatar: first(r.profilePicUrl, r.avatar, r.avatarLarger, r.profile_pic_url, null),
    verified: !!first(r.verified, r.isVerified, false),
    // UU PDP: only public business contact details, nothing scraped from DMs / private fields.
    contact: { email: email || null, whatsapp: wa ? '+' + wa : null },
    source: 'discovery',
    discoveredAt: new Date().toISOString(),
    discoveryQuery: combo.query,
  });
}
const chunks = [];
for (let i = 0; i < creators.length; i += 25) chunks.push(creators.slice(i, i + 25));
if (!chunks.length) return [{ json: { platform: combo.platform, niche: combo.niche, batchIndex: 0, batchCount: 0, count: 0, batch: [] } }];
return chunks.map((batch, i) => ({ json: { platform: combo.platform, niche: combo.niche, batchIndex: i, batchCount: chunks.length, count: batch.length, batch } }));

// Aggregate every loop run of "Map to Creator schema".
const rows = [];
for (let run = 0; run < 500; run++) {
  let items;
  try { items = $('Map to Creator schema').all(0, run); } catch (e) { break; }
  if (!items || !items.length) break;
  for (const it of items) rows.push(it.json);
}
const byCombo = {};
let total = 0;
for (const r of rows) { const k = r.platform + '/' + r.niche; byCombo[k] = (byCombo[k] || 0) + (r.count || 0); total += r.count || 0; }
const lines = Object.entries(byCombo).sort((a, b) => b[1] - a[1]).map(([k, v]) => '• ' + k + ': ' + v);
const source = ($('Build scan matrix').first().json || {}).source || 'schedule';
return [{ json: { total, combos: Object.keys(byCombo).length, source, text: '🔎 Discovery scan (' + source + ') finished: ' + total + ' creators across ' + Object.keys(byCombo).length + ' niche×platform combos\n' + lines.join('\n') } }];
